var report="Tools/UI/SharedCanvasesVerification.txt";System.IO.File.WriteAllText(report,"Authored shared canvases runtime verification\n");int phase=0,frame=-1,wait=0,index=0;string expectedScene="Lobby";var tested=new System.Collections.Generic.HashSet<int>();SharedCanvasDropdown current=null;double start=UnityEditor.EditorApplication.timeSinceStartup;UnityEditor.EditorApplication.CallbackFunction tick=null;
System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;UnityEngine.Time.timeScale=1;UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene=null;UnityEditor.EditorApplication.isPlaying=false;};
System.Func<int> countCanvases=()=>UnityEngine.Object.FindObjectsByType<UnityEngine.Canvas>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Count(c=>c.gameObject.scene.name==expectedScene);
tick=()=>{try{
 if(!UnityEditor.EditorApplication.isPlaying)return;UnityEngine.Application.runInBackground=true;if(UnityEditor.EditorApplication.timeSinceStartup-start>100)throw new System.Exception("timeout "+expectedScene+" phase="+phase);if(frame==UnityEngine.Time.frameCount)return;frame=UnityEngine.Time.frameCount;
 if(phase==0){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!=expectedScene||++wait<20)return;if(expectedScene=="Stage1"&&StageManager.Instance!=null)StageManager.Instance.StopRun();int expected=expectedScene=="Lobby"?1:2;if(countCanvases()!=expected)throw new System.Exception("canvas count="+countCanvases()+" expected="+expected);System.IO.File.AppendAllText(report,expectedScene+" canvases="+expected+"\n");phase=1;}
 if(phase==1){var next=UnityEngine.Object.FindObjectsByType<SharedCanvasDropdown>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).FirstOrDefault(d=>d.gameObject.scene.name==expectedScene&&!tested.Contains(d.GetInstanceID()));if(next==null){if(expectedScene=="Lobby"){var lobby=UnityEngine.Object.FindFirstObjectByType<LobbyController>();lobby.QuitGame();var dialog=UnityEngine.Object.FindObjectsByType<QuitConfirmationDialog>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Single();if(!dialog.gameObject.activeInHierarchy||countCanvases()!=1)throw new System.Exception("authored quit dialog failed");dialog.Hide();System.IO.File.AppendAllText(report,"PASS quit dialog uses shared canvas\n");expectedScene="Stage1";UnityEngine.SceneManagement.SceneManager.LoadScene("Stage1");phase=0;wait=0;return;}System.IO.File.AppendAllText(report,"COMPLETE\n");finish();return;}current=next;for(var p=current.transform;p!=null;p=p.parent)p.gameObject.SetActive(true);current.interactable=true;wait=0;phase=3;return;}
 if(phase==3){if(++wait<10)return;for(var p=current.transform;p!=null;p=p.parent)p.gameObject.SetActive(true);current.interactable=true;current.Show();if(!current.IsExpanded)throw new System.Exception("dropdown did not open "+current.name);wait=0;phase=2;return;}
 if(phase==2){if(++wait<5)return;var root=current.template;var toggles=root.GetComponentsInChildren<UnityEngine.UI.Toggle>(true).Where(t=>t.gameObject.activeInHierarchy).ToArray();if(toggles.Length!=current.options.Count)throw new System.Exception("wrong option count "+current.name+" expected="+current.options.Count+" actual="+toggles.Length+" dropdownActive="+current.gameObject.activeInHierarchy+" expanded="+current.IsExpanded+" templateSelf="+root.gameObject.activeSelf+" popup="+root.parent.gameObject.activeSelf+" rootActive="+root.gameObject.activeInHierarchy+" rows="+string.Join(",",root.GetComponentsInChildren<UnityEngine.UI.Toggle>(true).Select(t=>t.name+":"+t.gameObject.activeSelf)));if(countCanvases()!=(expectedScene=="Lobby"?1:2))throw new System.Exception("dropdown added canvas");var row=toggles[UnityEngine.Mathf.Clamp(current.value,0,toggles.Length-1)];var rect=(UnityEngine.RectTransform)row.transform;var canvas=row.GetComponentInParent<UnityEngine.Canvas>();var pos=UnityEngine.RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,rect.TransformPoint(rect.rect.center));var data=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=pos};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(data,hits);if(!hits.Any(h=>h.gameObject.transform.IsChildOf(row.transform)||h.gameObject==row.gameObject))throw new System.Exception("dropdown option not raycastable "+current.name+" at "+pos);UnityEngine.EventSystems.ExecuteEvents.Execute(row.gameObject,data,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);if(current.IsExpanded)throw new System.Exception("dropdown did not close");tested.Add(current.GetInstanceID());System.IO.File.AppendAllText(report,"PASS "+expectedScene+" "+current.name+" options="+toggles.Length+" click target valid, no extra canvas\n");phase=1;}
}catch(System.Exception e){System.IO.File.AppendAllText(report,"FAIL "+e+"\n");finish();}};
UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.SceneAsset>("Assets/Scenes/Lobby.unity");UnityEditor.EditorApplication.update+=tick;UnityEditor.EditorApplication.isPlaying=true;return "Testing dropdowns, quit dialog and canvas counts";
